"""A tiny calculator CLI. add and subtract work; multiply is missing."""
import sys


def add(a, b):
    return a + b


def subtract(a, b):
    return a - b


def main(argv):
    if len(argv) != 4:
        print("usage: calc.py <add|subtract> <a> <b>")
        return 2
    op, a, b = argv[1], float(argv[2]), float(argv[3])
    if op == "add":
        print(add(a, b))
    elif op == "subtract":
        print(subtract(a, b))
    else:
        print(f"unknown op: {op}")
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

